import { useEffect, useState } from "react";


function FacultyList() {
  const [selectedFaculty, setSelectedFaculty] = useState(null);
  const [rating, setRating] = useState("");
  const [comment, setComment] = useState("");
  const [faculties, setFaculties] = useState([]);
  const [facultyFeedback, setFacultyFeedback] = useState(null);
  const [loading, setLoading] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");

  useEffect(() => {
    fetchFaculties();
  }, []);

  const fetchFaculties = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/faculties", {
        method: "GET",
        headers: {
          "Authorization": "Bearer " + token
        }
      });

      const data = await response.json();
      setFaculties(data);

    } catch (error) {
      console.error("Error:", error);
    }
  };

  const handleSubmit = async () => {
    try {
      const token = localStorage.getItem("token");

      const response = await fetch("http://localhost:5001/feedback", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": "Bearer " + token
        },
        body: JSON.stringify({
          faculty_id: selectedFaculty.id,
          rating: rating,
          comment: comment
        })
      });

      const data = await response.json();

      if (response.ok) {
        alert("Feedback submitted..");
      } else {
        alert(data.message);
      }

    } catch (error) {
      console.error(error);
    }
  };

  const fetchFeedback = async (facultyId) => {
    try {
      setLoading(true);
      const token = localStorage.getItem("token");

      const response = await fetch(`http://localhost:5001/faculties/${facultyId}/feedback`, {
        method: "GET",
        headers: {
          "Authorization": "Bearer " + token
        }
      });

      const data = await response.json();

      if (response.ok) {
        setFacultyFeedback(data);
      } else {
        alert(data.message);
      }

    } catch (error) {
      console.error(error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div>
      <h2>Faculty List</h2>

      <input
        type="text"
        placeholder="Search faculty by name..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
      />

      {faculties
        .filter((faculty) =>
          faculty.name.toLowerCase().includes(searchTerm.toLowerCase())
        )
        .map((faculty) => (
        <div className="faculty-card" key={faculty.id}>
          <p><b>{faculty.name}</b></p>
          <p><b>Designation:</b> {faculty.designation}</p>
          <p><b>Department:</b> {faculty.department}</p>
          <p><b>Email:</b> {faculty.email}</p>
          <p><b>Mobile:</b> {faculty.mobile_no}</p>

          <button onClick={() => setSelectedFaculty(faculty)}>
            Give Feedback
          </button>

          <button onClick={() => fetchFeedback(faculty.id)}>
            View Feedback
          </button>
        </div>
      ))}

      {selectedFaculty && (
        <div className="feedback-box">
          <h3>Feedback for {selectedFaculty.name}</h3>

          <input
            type="number"
            placeholder="Rating (1-5)"
            onChange={(e) => setRating(e.target.value)}
          />

          <input
            type="text"
            placeholder="Comment"
            onChange={(e) => setComment(e.target.value)}
          />

          <button onClick={handleSubmit}>Submit Feedback</button>
        </div>
      )}

      {loading && <p>Loading feedback...</p>}

      {faculties.map((faculty) => (
  <div key={faculty.id}>
    <p><b>{faculty.name}</b></p>
    <p><b>Designation:</b> {faculty.designation}</p>
    <p><b>Department:</b> {faculty.department}</p>
    <p><b>Email:</b> {faculty.email}</p>
    <p><b>Mobile:</b> {faculty.mobile_no}</p>

    <button
      onClick={() => {
        setSelectedFaculty(faculty);
        setFacultyFeedback(null);
      }}
    >
      Give Feedback
    </button>

    <button onClick={() => fetchFeedback(faculty.id)}>
      View Feedback
    </button>

    {selectedFaculty?.id === faculty.id && (
      <div>
        <h3>Feedback for {selectedFaculty.name}</h3>

        <input
          type="number"
          placeholder="rating (1-5)"
          value={rating}
          onChange={(e) => setRating(e.target.value)}
        />

        <br /><br />

        <input
          type="text"
          placeholder="comment"
          value={comment}
          onChange={(e) => setComment(e.target.value)}
        />

        <br /><br />

        console.log("Submit button clicked");
        <button onClick={handleSubmit }>Submit Feedback</button>
      </div>
    )}
    <hr />
  </div>
))}
    </div>
  );
}

export default FacultyList;
